3828	void RenderProcessHostImpl::AppendRendererCommandLine(
3829	    base::CommandLine* command_line) {
3830	  // Pass the process type first, so it shows first in process listings.
3831	  command_line->AppendSwitchASCII(switches::kProcessType,
3832	                                  switches::kRendererProcess);
3833	
3834	  if (IsForTopChromeWebUI()) {
3835	    command_line->AppendSwitch(switches::kTopChromeWebUI);
3836	  }
3837	
3838	  if (ShouldSendGpuChannelEarly()) {
3839	    command_line->AppendSwitchASCII(
3840	        switches::kGpuClientId, base::NumberToString(gpu_client_->client_id()));
3841	  }
3842	
3843	  // Call this as early as possible so that --extension-process will show early
3844	  // in process listings. See https://crbug.com/1211558 for details.
3845	  GetContentClient()->browser()->AppendExtraCommandLineSwitches(
3846	      command_line, GetDeprecatedID());
3847	
3848	  if (IsPdf())
3849	    command_line->AppendSwitch(switches::kPdfRenderer);
3850	
3851	#if BUILDFLAG(IS_WIN)
3852	  if (command_line->HasSwitch(kExtensionProcess)) {
3853	    command_line->AppendArgNative(app_launch_prefetch::GetPrefetchSwitch(
3854	        app_launch_prefetch::SubprocessType::kExtension));
3855	  } else {
3856	    command_line->AppendArgNative(app_launch_prefetch::GetPrefetchSwitch(
3857	        app_launch_prefetch::SubprocessType::kRenderer));
3858	  }
3859	#endif  // BUILDFLAG(IS_WIN)
3860	
3861	  // Now send any options from our own command line we want to propagate.
3862	  const base::CommandLine& browser_command_line =
3863	      *base::CommandLine::ForCurrentProcess();
3864	  PropagateBrowserCommandLineToRenderer(browser_command_line, command_line);
3865	
3866	  // Pass on the browser locale.
3867	  const base::i18n::LanguageTag locale =
3868	      GetContentClient()->browser()->GetApplicationLocale();
3869	  command_line->AppendSwitchASCII(switches::kLang, locale.tag_string());
3870	
3871	  // A non-empty RendererCmdPrefix implies that Zygote is disabled.
3872	  if (!base::CommandLine::ForCurrentProcess()
3873	           ->GetSwitchValueNative(switches::kRendererCmdPrefix)
3874	           .empty()) {
3875	    command_line->AppendSwitch(switches::kNoZygote);
3876	  }
3877	
3878	  if (IsJitDisabled()) {
3879	    AppendToCommaSeparatedSwitch(
3880	        command_line, blink::switches::kJavaScriptFlags, "--jitless");
3881	  } else if (AreV8OptimizationsDisabled()) {
